mapper.select:
SELECT s.salary_id, s.employee_id, s.salary_period, s.base_salary, s.overtime_pay, s.bonus, s.deduction, s.net_salary, s.pay_date, s.status, e.employee_name, e.employee_no, d.department_name FROM salary s LEFT JOIN employee e ON s.employee_id = e.employee_id LEFT JOIN department d ON e.department_id = d.department_id WHERE s.employee_id = #{employeeId}
AND s.pay_date >= #{startDate}
AND s.pay_date <= #{endDate}
AND s.status = #{status}
ORDER BY s.pay_date DESC

SELECT s.salary_id, s.employee_id, e.employee_name, e.employee_no, d.department_name, s.base_salary, s.bonus, s.net_salary, s.pay_date, s.pay_period_start, s.pay_period_end, s.status FROM salary s LEFT JOIN employee e ON s.employee_id = e.employee_id LEFT JOIN department d ON e.department_id = d.department_id
AND s.employee_id = #{employeeId}
AND e.employee_name LIKE CONCAT('%', #{employeeName}, '%')
AND e.department_id = #{departmentId}
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND s.status = #{status}
AND s.net_salary >= #{minSalary}
AND s.net_salary <= #{maxSalary}
ORDER BY s.pay_date DESC, s.employee_id ASC

SELECT COUNT(*) as total_records, SUM(s.net_salary) as total_salary, AVG(s.net_salary) as avg_salary, MAX(s.net_salary) as max_salary, MIN(s.net_salary) as min_salary, SUM(s.base_salary) as total_base_salary, SUM(s.bonus) as total_bonus, SUM(s.allowance) as total_allowance, SUM(s.deduction) as total_deduction, SUM(s.overtime_pay) as total_overtime_pay, SUM(s.commission) as total_commission, SUM(s.tax_amount) as total_tax, COUNT(DISTINCT s.employee_id) as employee_count FROM salary s
AND EXISTS ( SELECT 1 FROM employee e WHERE e.employee_id = s.employee_id AND e.department_id = #{departmentId} )
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND s.status = #{status}

SELECT d.department_id, d.department_name, COUNT(DISTINCT s.employee_id) as employee_count, COUNT(s.salary_id) as salary_records, SUM(s.net_salary) as total_salary, AVG(s.net_salary) as avg_salary, MAX(s.net_salary) as max_salary, MIN(s.net_salary) as min_salary, SUM(s.bonus) as total_bonus, AVG(s.bonus) as avg_bonus, SUM(s.overtime_pay) as total_overtime_pay FROM salary s JOIN employee e ON s.employee_id = e.employee_id JOIN department d ON e.department_id = d.department_id
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND s.status = #{status}
GROUP BY d.department_id, d.department_name ORDER BY avg_salary DESC

SELECT YEAR(s.pay_date) as year, MONTH(s.pay_date) as month, DATE_FORMAT(s.pay_date, '%Y-%m') as year_month, COUNT(*) as record_count, COUNT(DISTINCT s.employee_id) as employee_count, SUM(s.net_salary) as total_salary, AVG(s.net_salary) as avg_salary, SUM(s.base_salary) as total_base_salary, SUM(s.bonus) as total_bonus, SUM(s.overtime_pay) as total_overtime_pay FROM salary s
AND YEAR(s.pay_date) >= #{startYear}
AND YEAR(s.pay_date) <= #{endYear}
AND EXISTS ( SELECT 1 FROM employee e WHERE e.employee_id = s.employee_id AND e.department_id = #{departmentId} )
AND s.status = #{status}
GROUP BY YEAR(s.pay_date), MONTH(s.pay_date) ORDER BY year DESC, month DESC

SELECT e.employee_id, e.employee_name, e.employee_no, d.department_name, e.position, AVG(s.net_salary) as avg_salary, MAX(s.net_salary) as max_salary, MIN(s.net_salary) as min_salary, SUM(s.bonus) as total_bonus, COUNT(s.salary_id) as pay_periods, RANK() OVER (ORDER BY AVG(s.net_salary) DESC) as salary_rank, DENSE_RANK() OVER (PARTITION BY d.department_id ORDER BY AVG(s.net_salary) DESC) as dept_rank FROM salary s JOIN employee e ON s.employee_id = e.employee_id JOIN department d ON e.department_id = d.department_id
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND e.department_id = #{departmentId}
AND s.status = #{status}
GROUP BY e.employee_id, e.employee_name, e.employee_no, d.department_name, e.position
LIMIT #{limit}

SELECT s.salary_id, s.employee_id, e.employee_name, d.department_name, s.net_salary, s.pay_date, dept_avg.avg_salary as dept_avg_salary, ABS(s.net_salary - dept_avg.avg_salary) as deviation, CASE WHEN s.net_salary > dept_avg.avg_salary * 1.5 THEN 'HIGH_ANOMALY' WHEN s.net_salary < dept_avg.avg_salary * 0.5 THEN 'LOW_ANOMALY' WHEN s.net_salary > dept_avg.avg_salary * 1.2 THEN 'HIGH_WARNING' WHEN s.net_salary < dept_avg.avg_salary * 0.8 THEN 'LOW_WARNING' ELSE 'NORMAL' END as anomaly_type, ROUND((s.net_salary / dept_avg.avg_salary - 1) * 100, 2) as deviation_percentage FROM salary s JOIN employee e ON s.employee_id = e.employee_id JOIN department d ON e.department_id = d.department_id JOIN ( SELECT e2.department_id, AVG(s2.net_salary) as avg_salary FROM salary s2 JOIN employee e2 ON s2.employee_id = e2.employee_id
AND s2.pay_date >= #{payDateStart}
AND s2.pay_date <= #{payDateEnd}
AND s2.status = #{status}
GROUP BY e2.department_id ) dept_avg ON e.department_id = dept_avg.department_id
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND s.status = #{status}
AND s.net_salary > dept_avg.avg_salary * 1.5
AND s.net_salary < dept_avg.avg_salary * 0.5
AND s.net_salary > dept_avg.avg_salary * 1.2 AND s.net_salary <= dept_avg.avg_salary * 1.5
AND s.net_salary < dept_avg.avg_salary * 0.8 AND s.net_salary >= dept_avg.avg_salary * 0.5
ORDER BY ABS(s.net_salary - dept_avg.avg_salary) DESC

SELECT d.department_id, d.department_name, d.budget as dept_budget, COALESCE(salary_data.total_salary_cost, 0) as actual_salary_cost, COALESCE(salary_data.employee_count, 0) as employee_count, COALESCE(salary_data.avg_salary, 0) as avg_salary, (d.budget - COALESCE(salary_data.total_salary_cost, 0)) as budget_remaining, CASE WHEN d.budget > 0 THEN ROUND((COALESCE(salary_data.total_salary_cost, 0) / d.budget) * 100, 2) ELSE 0 END as budget_usage_percentage, CASE WHEN COALESCE(salary_data.total_salary_cost, 0) > d.budget THEN 'OVER_BUDGET' WHEN COALESCE(salary_data.total_salary_cost, 0) > d.budget * 0.9 THEN 'WARNING' WHEN COALESCE(salary_data.total_salary_cost, 0) > d.budget * 0.8 THEN 'CAUTION' ELSE 'NORMAL' END as budget_status FROM department d LEFT JOIN ( SELECT e.department_id, SUM(s.net_salary) as total_salary_cost, COUNT(DISTINCT s.employee_id) as employee_count, AVG(s.net_salary) as avg_salary FROM salary s JOIN employee e ON s.employee_id = e.employee_id
AND s.pay_date >= #{payDateStart}
AND s.pay_date <= #{payDateEnd}
AND s.status = #{status}
GROUP BY e.department_id ) salary_data ON d.department_id = salary_data.department_id
AND d.department_id = #{departmentId}
AND COALESCE(salary_data.total_salary_cost, 0) > d.budget
AND COALESCE(salary_data.total_salary_cost, 0) > d.budget * 0.9 AND COALESCE(salary_data.total_salary_cost, 0) <= d.budget
AND COALESCE(salary_data.total_salary_cost, 0) > d.budget * 0.8 AND COALESCE(salary_data.total_salary_cost, 0) <= d.budget * 0.9
AND COALESCE(salary_data.total_salary_cost, 0) <= d.budget * 0.8
ORDER BY budget_usage_percentage DESC
